import {
  CreateDateColumn,
  DeleteDateColumn,
  PrimaryColumn,
  UpdateDateColumn,
  VersionColumn,
} from 'typeorm';
import { TimestampTransformer } from '../transformers/timestamp-transformer.js';

/**
 * Base of every entity: UUIDv7 id generated by the application, version for optimistic locking,
 * dates in `timestamptz` and soft delete.
 */
export abstract class VersionedEntity {
  @PrimaryColumn({ type: 'uuid', name: 'id' })
  id!: string;

  /** Unset while the entity is not saved; the database starts it at 1 and increments it on each update. */
  @VersionColumn({ name: 'version' })
  version?: number;

  @CreateDateColumn({
    type: 'timestamptz',
    name: 'created_at',
    transformer: new TimestampTransformer(),
  })
  createdAt?: Date;

  @UpdateDateColumn({
    type: 'timestamptz',
    name: 'updated_at',
    transformer: new TimestampTransformer(),
  })
  updatedAt?: Date;

  /** When set, the row is deleted: TypeORM reads hide it. */
  @DeleteDateColumn({
    type: 'timestamptz',
    name: 'deleted_at',
    nullable: true,
    transformer: new TimestampTransformer(),
  })
  deletedAt?: Date | null;
}
